// 1. Initialize Resumable Multipart Video Upload
POST /api/v1/videos/uploads/init
Request:
{
  "creator_id": "usr_7712",
  "title": "System Design Deep Dive: Distributed Consensus",
  "file_size_bytes": 1073741824,
  "part_size_bytes": 67108864
}
Response (201 Created):
{
  "video_id": "v_9xK2pQ1a",
  "s3_upload_id": "upl_01HV9Z9912",
  "presigned_part_urls": [
    { "part_number": 1, "put_url": "https://s3.amazonaws.com/god-raw-video/v_9xK2pQ1a?partNumber=1&." }
  ]
}

// 2. Fetch Adaptive Bitrate Playback Manifest
GET /api/v1/videos/v_9xK2pQ1a/playback
Response (200 OK):
{
  "video_id": "v_9xK2pQ1a",
  "status": "READY",
  "hls_master_playlist_url": "https://edge-bom01.cdn.god.ly/v/v_9xK2pQ1a/master.m3u8?token=.",
  "dash_manifest_url": "https://edge-bom01.cdn.god.ly/v/v_9xK2pQ1a/manifest.mpd?token=.",
  "available_renditions": ["360p_h264", "720p_h264", "1080p_vp9", "2160p_av1"]
}

// ---------------------------------------------------------------------------
// Core Storage Entities & Schema Definitions
// ---------------------------------------------------------------------------
ENTITY videos_metadata (Sharded MySQL (Vitess)) {
  [PK ] video_id               VARCHAR(16)
  [IDX] creator_id             UUID
        title                  VARCHAR(255)
        status                 ENUM('UPLOADING','TRANSCODING','READY')
        duration_seconds       INT
}

ENTITY transcode_renditions (Sharded MySQL (Vitess)) {
  [PK ] rendition_id           UUID
  [FK ] video_id               VARCHAR(16)
        profile                ENUM('360p','720p','1080p','4K')
        codec                  ENUM('H264','VP9','AV1')
        playlist_s3_uri        VARCHAR(512)
}

ENTITY gop_video_segments (S3 Origin + ISP Edge CDN Cache) {
  [PK ] rendition_id           UUID (Composite PK)
  [PK ] segment_seq_no         INT (0.N, 4s GOP)
        fmp4_cdn_path          VARCHAR (/v/{id}/1080p/seg_N.m4s)
        size_bytes             INT
}

// Relationships: videos_metadata --(1 : N (encoded profiles))--> transcode_renditions --(1 : N (4-second fMP4 chunks))--> gop_video_segments
